/**
 * 🛡️ SOURCE CREDIT & COPYRIGHT GUARD — KONFIGURASI (FITUR BARU!)
 * =====================================================================
 * Satu-satunya tempat untuk membaca/mengubah env var fitur ini — pola sama
 * dengan channel-monitor-config.ts / duplicate-filter-config.ts, jadi cukup
 * ubah di Railway → Variables (restart service), tanpa menyentuh kode lain.
 *
 * Tujuan: Auto-Monitor mengambil video channel lain secara otomatis, risiko
 * terbesarnya copyright strike / penolakan monetisasi (reused content).
 * Fitur ini menambah 3 pengaman:
 *   1. Source Credit  → deskripsi klip otomatis diberi "Source: <judul> — <channel> <link>"
 *   2. Whitelist      → hanya channel milik sendiri / yang sudah diizinkan
 *   3. Batas & Content ID → maks klip per video sumber per hari + skip video
 *                           yang punya tanda Content ID
 *
 * =====================================================================
 * ENV VARS (semua opsional, semua punya default aman)
 * =====================================================================
 * SOURCE_CREDIT_ENABLED=true
 *   Tambah baris kredit sumber di deskripsi YouTube setiap klip.
 *
 * SOURCE_CREDIT_TEMPLATE="Source: {title} — {channel} {url}"
 *   Format baris kredit. Placeholder: {title} {channel} {url}.
 *   Kalau nama channel tidak diketahui, "— {channel}" dibuang otomatis.
 *
 * SOURCE_CREDIT_POSITION=bottom        (bottom | top)
 *   bottom = di akhir deskripsi (sebelum baris hashtag), top = paling atas.
 *
 * COPYRIGHT_GUARD_MODE=warn            (warn | block | off)
 *   warn  = pelanggaran hanya diberi PERINGATAN (progress Telegram + log),
 *           proses tetap lanjut. DEFAULT — tidak mengubah perilaku lama.
 *   block = pelanggaran MEMBLOKIR job (video di-skip, tidak di-download).
 *           Batas klip/hari juga dipaksa (klip dipangkas / job ditolak).
 *   off   = guard dimatikan total (kredit sumber tetap jalan kalau aktif).
 *
 * COPYRIGHT_GUARD_SCOPE=all            (all | monitor)
 *   all     = berlaku untuk semua job (link manual + Auto-Monitor).
 *   monitor = hanya untuk job hasil Auto-Monitor (link manual bebas).
 *
 * COPYRIGHT_WHITELIST_CHANNELS=
 *   Daftar channel yang diizinkan, pisahkan dengan koma. Boleh ID channel
 *   (UCxxxx), @handle, nama channel, atau URL channel. Contoh:
 *     COPYRIGHT_WHITELIST_CHANNELS=UCabc123,@channelku,https://youtube.com/@mitra
 *   Selain env ini, tiap user bisa menambah lewat Telegram: /whitelist add ...
 *   Whitelist AKTIF kalau ada isinya (env/Telegram) atau
 *   COPYRIGHT_WHITELIST_REQUIRED=true.
 *
 * COPYRIGHT_WHITELIST_REQUIRED=false
 *   true = whitelist selalu dipaksa walau kosong (kalau kosong, hanya channel
 *   milik sendiri yang lolos).
 *
 * COPYRIGHT_ALLOW_OWN_CHANNEL=true
 *   Channel YouTube yang terhubung lewat /connect otomatis dianggap "milik
 *   sendiri" (butuh izin youtube.readonly — ANALYTICS_REQUEST_READONLY_SCOPE=true).
 *
 * COPYRIGHT_MAX_CLIPS_PER_SOURCE_PER_DAY=3   (0 = tanpa batas)
 *   Maks klip yang dibuat dari SATU video sumber dalam sehari.
 *
 * COPYRIGHT_DAY_TIMEZONE=Asia/Jakarta
 *   Zona waktu untuk pergantian "hari" (default ikut SCHEDULER_TIMEZONE).
 *
 * COPYRIGHT_SKIP_CONTENT_ID=true
 *   Skip video yang punya tanda Content ID (musik berlisensi di panel
 *   "Music in this video", deskripsi "Provided to YouTube by", dsb.).
 *
 * COPYRIGHT_CONTENT_ID_MUSIC_SIGNAL=true
 *   Anggap metadata musik (track/artist/album dari YouTube) sebagai tanda
 *   Content ID. Matikan kalau terlalu banyak video yang ter-skip.
 *
 * COPYRIGHT_CONTENT_ID_KEYWORDS=
 *   Kata kunci tambahan (pisah koma) yang dianggap tanda Content ID bila
 *   muncul di judul/deskripsi/nama channel sumber.
 *
 * COPYRIGHT_PREFLIGHT_TIMEOUT_MS=45000
 *   Batas waktu pengambilan metadata video sumber (yt-dlp) sebelum download.
 */

export type CopyrightGuardMode = "warn" | "block" | "off";
export type CopyrightGuardScope = "all" | "monitor";
export type SourceCreditPosition = "top" | "bottom";

export const DEFAULT_CREDIT_TEMPLATE = "Source: {title} — {channel} {url}";

/** Penanda Content ID bawaan (huruf kecil). Tambah/ubah di sini atau via env. */
export const DEFAULT_CONTENT_ID_KEYWORDS: string[] = [
  "provided to youtube by",
  "auto-generated by youtube",
  "licensed to youtube by",
  "℗",
  "content id",
  "contentid",
  "copyright claim",
  "claimed by",
];

function boolEnv(raw: string | undefined, fallback: boolean): boolean {
  if (raw === undefined || raw.trim() === "") return fallback;
  return ["true", "1", "yes", "on"].includes(raw.toLowerCase().trim());
}

function intEnv(raw: string | undefined, fallback: number, min: number, max: number): number {
  if (!raw) return fallback;
  const parsed = parseInt(raw.trim(), 10);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.min(max, Math.max(min, parsed));
}

function listEnv(raw: string | undefined): string[] {
  return (raw || "")
    .split(/[,\n;]/)
    .map((s) => s.trim())
    .filter(Boolean);
}

export function isSourceCreditEnabled(): boolean {
  return boolEnv(process.env.SOURCE_CREDIT_ENABLED, true);
}

export function getSourceCreditTemplate(): string {
  const raw = process.env.SOURCE_CREDIT_TEMPLATE?.trim();
  return raw || DEFAULT_CREDIT_TEMPLATE;
}

export function getSourceCreditPosition(): SourceCreditPosition {
  return process.env.SOURCE_CREDIT_POSITION?.toLowerCase().trim() === "top" ? "top" : "bottom";
}

export function getCopyrightGuardMode(): CopyrightGuardMode {
  const raw = (process.env.COPYRIGHT_GUARD_MODE || "").toLowerCase().trim();
  if (raw === "block") return "block";
  if (raw === "off" || raw === "false" || raw === "disabled") return "off";
  return "warn";
}

export function getCopyrightGuardScope(): CopyrightGuardScope {
  return process.env.COPYRIGHT_GUARD_SCOPE?.toLowerCase().trim() === "monitor" ? "monitor" : "all";
}

export function getEnvWhitelist(): string[] {
  return listEnv(process.env.COPYRIGHT_WHITELIST_CHANNELS);
}

export function isWhitelistRequired(): boolean {
  return boolEnv(process.env.COPYRIGHT_WHITELIST_REQUIRED, false);
}

export function isOwnChannelAllowed(): boolean {
  return boolEnv(process.env.COPYRIGHT_ALLOW_OWN_CHANNEL, true);
}

export function getMaxClipsPerSourcePerDay(): number {
  return intEnv(process.env.COPYRIGHT_MAX_CLIPS_PER_SOURCE_PER_DAY, 3, 0, 100);
}

export function getGuardTimezone(): string {
  const candidate =
    process.env.COPYRIGHT_DAY_TIMEZONE?.trim() || process.env.SCHEDULER_TIMEZONE?.trim() || "Asia/Jakarta";
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: candidate });
    return candidate;
  } catch {
    return "Asia/Jakarta";
  }
}

export function isSkipContentIdEnabled(): boolean {
  return boolEnv(process.env.COPYRIGHT_SKIP_CONTENT_ID, true);
}

export function isMusicSignalEnabled(): boolean {
  return boolEnv(process.env.COPYRIGHT_CONTENT_ID_MUSIC_SIGNAL, true);
}

export function getContentIdKeywords(): string[] {
  const extra = listEnv(process.env.COPYRIGHT_CONTENT_ID_KEYWORDS).map((k) => k.toLowerCase());
  return Array.from(new Set([...DEFAULT_CONTENT_ID_KEYWORDS, ...extra]));
}

export function getPreflightTimeoutMs(): number {
  return intEnv(process.env.COPYRIGHT_PREFLIGHT_TIMEOUT_MS, 45_000, 5_000, 180_000);
}

/** Ringkasan semua konfigurasi aktif — dipakai dashboard & perintah Telegram. */
export function getSourceGuardConfigSummary() {
  return {
    creditEnabled: isSourceCreditEnabled(),
    creditTemplate: getSourceCreditTemplate(),
    creditPosition: getSourceCreditPosition(),
    mode: getCopyrightGuardMode(),
    scope: getCopyrightGuardScope(),
    whitelist: getEnvWhitelist(),
    whitelistRequired: isWhitelistRequired(),
    allowOwnChannel: isOwnChannelAllowed(),
    maxClipsPerSourcePerDay: getMaxClipsPerSourcePerDay(),
    timezone: getGuardTimezone(),
    skipContentId: isSkipContentIdEnabled(),
    musicSignal: isMusicSignalEnabled(),
    extraKeywords: listEnv(process.env.COPYRIGHT_CONTENT_ID_KEYWORDS),
  };
}
